const WORDMARK_WIDTH = 100.1
const WORDMARK_CAP = 18.2

export const Wordmark = (props: { class?: string }) => {
  return (
    <svg
      data-component="logo-wordmark"
      classList={{ [props.class ?? ""]: !!props.class }}
      viewBox={`0 ${-WORDMARK_CAP} ${WORDMARK_WIDTH} ${WORDMARK_CAP}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label="Praex"
    >
      <path d={WORDMARK} fill="currentColor" />
    </svg>
  )
}

export const Mark = (props: { class?: string }) => {
  return (
    <svg
      data-component="logo-mark"
      classList={{ [props.class ?? ""]: !!props.class }}
      viewBox="0 0 16 20"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <rect
        data-slot="logo-logo-mark-tile"
        x="0.25"
        y="2.25"
        width="15.5"
        height="15.5"
        rx="3.4"
        fill="#000000"
        stroke="rgba(255, 255, 255, 0.24)"
        stroke-width="0.6"
      />
      <path
        data-slot="logo-logo-mark-wave"
        d={wave(0, 2, 16)}
        stroke="#ffffff"
        stroke-width="2.1"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
    </svg>
  )
}

export const Splash = (props: Pick<ComponentProps<"svg">, "ref" | "class">) => {
  return (
    <svg
      ref={props.ref}
      data-component="logo-splash"
      classList={{ [props.class ?? ""]: !!props.class }}
      viewBox="0 0 80 100"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <rect x="1" y="11" width="78" height="78" rx="16.5" fill="#000000" stroke="rgba(255, 255, 255, 0.24)" stroke-width="2" />
      <path
        d={wave(0, 10, 80)}
        stroke="#ffffff"
        stroke-width="9.6"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
    </svg>
  )
}

export const Logo = (props: { class?: string }) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 158 42"
      fill="none"
      classList={{ [props.class ?? ""]: !!props.class }}
    >
      {/* the mark keeps its colours in both themes: white wave on a black tile, hairline edge */}
      <rect x="0.5" y="0.5" width="41" height="41" rx="8.5" fill="#000000" stroke="rgba(255, 255, 255, 0.24)" stroke-width="1" />
      <path
        d={wave(0, 0, 42)}
        stroke="#fafafa"
        stroke-width="5"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
      <path d={WORDMARK} fill="var(--icon-strong-base)" transform="translate(58 30.1)" />
    </svg>
  )
}
